<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;font-size:12px">Convolutional layer explorer</div>

<label style="margin-top:2px">Number of filters in bank: <b id="nfVal">96</b>
  <input type="range" id="numFilters" min="1" max="96" step="1" value="96">
</label>

