// face grids (2)          → LineSegments 8×8 on the right-hand 128×128 face of each slab
// receptive field patch   → PlaneGeometry(1.125) rotated to YZ, red 0.35 + red outline
// every text item         → addLabel() HTML, serif
*/

const BLACK = 0x000000, RED = 0xd64545, TINT = 0xf3c9c9;

const SLAB_H = 3.0, SLAB_D = 3.0;          // 128 (up) and 128 (receding)
const T_IN = 0.90;                          // 3 input channels (screen-right)
const X_IN_L = -5.30, X_IN_R = X_IN_L + T_IN;
const X_OUT_L = 4.30;
const MAX_SHEETS = 8;

/* ── generic helpers ───────────────────────────────────────────────── */
function mkLabel(html, pos, o = {}) {
  const e = addLabel(html, pos, o);
  e.div.style.fontFamily = 'Georgia,"Times New Roman",serif';
  return e;
}
function setVis(e, v) { e.div.style.visibility = v ? 'visible' : 'hidden'; }

function makeSheet(w, h, dd) {
  const geo = new THREE.BoxGeometry(w, h, dd);
  const mat = new THREE.MeshBasicMaterial({
    color: 0xffffff, transparent: true, opacity: 1,
    polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
  });
  const mesh = new THREE.Mesh(geo, mat);
  const eg = new THREE.EdgesGeometry(geo);
  const emat = new THREE.LineBasicMaterial({ color: BLACK, transparent: true, opacity: 1 });
  const edges = new THREE.LineSegments(eg, emat);
  const group = new THREE.Group();
  group.add(mesh, edges);
  return { group, mat, emat, geo, eg };
}
function disposeSheet(s) { s.geo.dispose(); s.eg.dispose(); s.mat.dispose(); s.emat.dispose(); }

function roundedRectShape(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2, y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y); s.absarc(x + w - r, y + r, r, -Math.PI / 2, 0, false);
  s.lineTo(x + w, y + h - r); s.absarc(x + w - r, y + h - r, r, 0, Math.PI / 2, false);
  s.lineTo(x + r, y + h); s.absarc(x + r, y + h - r, r, Math.PI / 2, Math.PI, false);
  s.lineTo(x, y + r); s.absarc(x + r, y + r, r, Math.PI, 1.5 * Math.PI, false);
  return s;
}
function ringMesh(outerShape, innerShape, color) {
  const hole = new THREE.Path(innerShape.getPoints(80).reverse());
  outerShape.holes.push(hole);
  const geo = new THREE.ShapeGeometry(outerShape, 24);
  return new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
}
function polyShape(pts) {
  return new THREE.Shape(pts.map(p => new THREE.Vector2(p[0], p[1])));
}

/* ── hollow block arrow (outline only) ─────────────────────────────── */
function blockArrow(L, sh, hh, hl, t) {
  const h = L / 2, b = L / 2 - hl, L2 = Math.hypot(hl, hh);
  const outer = [[-h, sh], [b, sh], [b, hh], [h, 0], [b, -hh], [b, -sh], [-h, -sh]];
  const y1 = sh - t, x1 = b + t;
  const P0x = b - t * hh / L2, P0y = hh - t * hl / L2;
  const s3 = (x1 - P0x) / hl;
  const y3 = P0y - s3 * hh;
  const tipx = h - t * L2 / hh;
  const inner = [[-h + t, y1], [x1, y1], [x1, y3], [tipx, 0], [x1, -y3], [x1, -y1], [-h + t, -y1]];
  return ringMesh(polyShape(outer), polyShape(inner), BLACK);
}

/* ── input slab ────────────────────────────────────────────────────── */
const inGroup = new THREE.Group(); scene.add(inGroup);
const inSheets = [];
for (let i = 0; i < 3; i++) {
  const t = T_IN / 3;
  const s = makeSheet(t, SLAB_H, SLAB_D);
  s.group.position.set(X_IN_L + (i + 0.5) * t, 0, 0);
  inGroup.add(s.group);
  inSheets.push(s);
}

/* ── filter box ────────────────────────────────────────────────────── */
const BOX_W = 4.4, BOX_H = 1.70, BOX_R = 0.32, BOX_T = 0.075;
const boxGroup = new THREE.Group(); scene.add(boxGroup);
const boxFill = new THREE.Mesh(
  new THREE.ShapeGeometry(roundedRectShape(BOX_W - 2 * BOX_T, BOX_H - 2 * BOX_T, BOX_R - BOX_T), 24),
  new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide })
);
boxFill.position.z = -0.004;
boxGroup.add(boxFill);
boxGroup.add(ringMesh(
  roundedRectShape(BOX_W, BOX_H, BOX_R),
  roundedRectShape(BOX_W - 2 * BOX_T, BOX_H - 2 * BOX_T, BOX_R - BOX_T),
  BLACK));
boxGroup.position.set(0, 0, 0);

/* ── two hollow arrows ─────────────────────────────────────────────── */
const arrow1 = blockArrow(1.2, 0.20, 0.42, 0.50, 0.055); arrow1.position.set(-3.0, 0, 0);
const arrow2 = blockArrow(1.2, 0.20, 0.42, 0.50, 0.055); arrow2.position.set(3.0, 0, 0);
scene.add(arrow1, arrow2);

/* ── output slab (rebuilt by the slider) ───────────────────────────── */
const outGroup = new THREE.Group(); scene.add(outGroup);
let outSheets = [];
function outThickness(C) { return 0.30 + 2.40 * (C / 96); }
function sheetCount(C) { return Math.min(C, MAX_SHEETS); }

function rebuildOutput(C) {
  for (const s of outSheets) { outGroup.remove(s.group); disposeSheet(s); }
  outSheets = [];
  const T = outThickness(C), N = sheetCount(C), t = T / N;
  for (let i = 0; i < N; i++) {
    const s = makeSheet(t, SLAB_H, SLAB_D);
    s.group.position.set(X_OUT_L + (i + 0.5) * t, 0, 0);
    outGroup.add(s.group);
    outSheets.push(s);
  }
  return T;
}

/* ── spatial-view overlays ─────────────────────────────────────────── */
function makeGrid(n, size, color) {
  const pts = [], h = size / 2;
  for (let i = 0; i <= n; i++) {
    const u = -h + size * i / n;
    pts.push(new THREE.Vector3(0, u, -h), new THREE.Vector3(0, u, h));
    pts.push(new THREE.Vector3(0, -h, u), new THREE.Vector3(0, h, u));
  }
  return new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color }));
}
const gridIn = makeGrid(8, SLAB_D, 0x8a8a8a);
gridIn.position.set(X_IN_R + 0.008, 0, 0);
const gridOut = makeGrid(8, SLAB_D, 0x8a8a8a);
scene.add(gridIn, gridOut);

const patchGeo = new THREE.PlaneGeometry(SLAB_D * 3 / 8, SLAB_D * 3 / 8).rotateY(Math.PI / 2);
const patch = new THREE.Mesh(patchGeo, new THREE.MeshBasicMaterial({ color: RED, transparent: true, opacity: 0.35, side: THREE.DoubleSide }));
patch.position.set(X_IN_R + 0.012, -0.19, 0.38);
const patchEdge = new THREE.LineSegments(new THREE.EdgesGeometry(patchGeo),
  new THREE.LineBasicMaterial({ color: RED }));
patchEdge.position.copy(patch.position);
scene.add(patch, patchEdge);

/* ── filter cubes under the box ────────────────────────────────────── */
const CUBE = 0.38, PITCH = 0.50, CUBE_Y = -1.72;
const cubesGroup = new THREE.Group(); scene.add(cubesGroup);
const cubes = [];
for (let i = 0; i < MAX_SHEETS; i++) {
  const geo = new THREE.BoxGeometry(CUBE, CUBE, CUBE);
  const mat = new THREE.MeshBasicMaterial({ color: 0xffffff, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 });
  const mesh = new THREE.Mesh(geo, mat);
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geo), new THREE.LineBasicMaterial({ color: BLACK }));
  const g = new THREE.Group(); g.add(mesh, edges);
  cubesGroup.add(g);
  cubes.push({ group: g, mesh, mat });
  registerInteractive(mesh, {
    title: 'One 3×3×3 filter',
    body: 'Every filter spans all 3 input channels: 3×3 spatial × 3 channels = 27 weights (+1 bias). It slides over the whole 128×128 image and produces exactly ONE output channel, so 96 filters → 96 output channels.',
    tooltip: 'Filter: 3×3×3 = 27 weights',
    onClick: () => selectFilter(i)
  });
}

/* selected filter, drawn as its 27 individual weight cells */
const cellsGroup = new THREE.Group(); cellsGroup.visible = false; scene.add(cellsGroup);
{
  const cs = 0.10, gap = 0.125;
  for (let a = 0; a < 3; a++) for (let b = 0; b < 3; b++) for (let c = 0; c < 3; c++) {
    const geo = new THREE.BoxGeometry(cs, cs, cs);
    const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color: RED, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 }));
    const e = new THREE.LineSegments(new THREE.EdgesGeometry(geo), new THREE.LineBasicMaterial({ color: 0x7a1e1e }));
    const g = new THREE.Group();
    g.add(m, e);
    g.position.set((a - 1) * gap, (b - 1) * gap, (c - 1) * gap);
    cellsGroup.add(g);
  }
}

/* ── initial build, then camera ────────────────────────────────────── */
let numFilters = 96;
let emphasis = 'Channel view';
let selected = null;
let T_OUT = rebuildOutput(numFilters);
layoutCubes(numFilters);

setCameraView({
  projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5,
  rollDeg: 0, heightFraction: 0.6
});

/* ── labels ────────────────────────────────────────────────────────── */
const DIM = { fontSize: '16px' }, HEAD = { fontSize: '17px' };

const hdrIn = mkLabel('<b>x</b><sub>in</sub> &isin; &#8477;<sup>3&times;128&times;128</sup>',
  new THREE.Vector3((X_IN_L + X_IN_R) / 2, 2.80, 0), HEAD);
const hdrOut = mkLabel('', new THREE.Vector3(0, 2.80, 0), HEAD);

const lblIn3 = mkLabel('3', new THREE.Vector3((X_IN_L + X_IN_R) / 2, -1.95, 1.5), DIM);
const lblOutC = mkLabel('96', new THREE.Vector3(0, -1.95, 1.5), DIM);

mkLabel('128', new THREE.Vector3(X_IN_L - 0.30, 0, 1.5), DIM);
mkLabel('128', new THREE.Vector3(X_IN_L - 0.15, 1.78, 0), Object.assign({ offset: [-6, 0] }, DIM));

const lblOutH = mkLabel('128', new THREE.Vector3(0, 0.35, -1.5), DIM);
const lblOutD = mkLabel('128', new THREE.Vector3(0, -1.92, -0.55), DIM);

mkLabel('Filter Bank with', new THREE.Vector3(0, 0.30, 0.03), { fontSize: '19px' });
mkLabel('3x3 filters', new THREE.Vector3(0, -0.30, 0.03), { fontSize: '19px' });

const ellTop = mkLabel('&middot;&middot;&middot;', new THREE.Vector3(0, 1.52, -0.25), { fontSize: '20px', bold: true });
const ellFront = mkLabel('&middot;&middot;&middot;', new THREE.Vector3(0, -0.70, 1.52), { fontSize: '20px', bold: true });

const callout = mkLabel('3&times;3&times;3 = 27 weights', new THREE.Vector3(0, CUBE_Y + 0.42, 0),
  { fontSize: '12px', color: '#a01f1f', bold: true, background: '#ffffff' });
setVis(callout, false);

const cubesCaption = mkLabel('filters in the bank', new THREE.Vector3(0, CUBE_Y - 0.42, 0),
  { fontSize: '11px', color: '#666' });

/* ── layout / style updates ────────────────────────────────────────── */
function layoutCubes(C) {
  const n = sheetCount(C);
  for (let i = 0; i < MAX_SHEETS; i++) {
    cubes[i].group.visible = i < n;
    cubes[i].group.position.set((i - (n - 1) / 2) * PITCH, CUBE_Y, 0);
  }
}

function updateLabels(C) {
  const T = outThickness(C), xc = X_OUT_L + T / 2, xR = X_OUT_L + T;
  hdrOut.div.innerHTML = '<b>x</b><sub>out</sub> &isin; &#8477;<sup>' + C + '&times;128&times;128</sup>';
  hdrOut.pos.set(xc, 2.80, 0);
  lblOutC.div.innerHTML = String(C);
  lblOutC.pos.set(xc, -1.95, 1.5);
  lblOutH.pos.set(xR + 0.30, 0.35, -1.5);
  lblOutD.pos.set(xR + 0.22, -1.92, -0.55);
  ellTop.pos.set(X_OUT_L + T * 0.55, 1.52, -0.25);
  ellFront.pos.set(X_OUT_L + T * 0.45, -0.70, 1.52);
  const many = C > MAX_SHEETS;
  setVis(ellTop, many); setVis(ellFront, many);
  gridOut.position.set(xR + 0.008, 0, 0);
}

function applyStyles() {
  const spatial = emphasis === 'Spatial view';
  const faceOp = spatial ? 0.55 : 1.0;
  const edgeCol = spatial ? 0x9a9a9a : BLACK;

  inSheets.forEach(s => {
    const hl = selected !== null;
    s.mat.color.set(hl ? TINT : 0xffffff);
    s.mat.opacity = faceOp;
    s.emat.color.set(hl ? RED : edgeCol);
  });
  outSheets.forEach((s, i) => {
    const hl = selected !== null && i === selected;
    s.mat.color.set(hl ? TINT : 0xffffff);
    s.mat.opacity = faceOp;
    s.emat.color.set(hl ? RED : edgeCol);
  });
  cubes.forEach((c, i) => {
    c.mat.color.set(selected === i ? TINT : 0xffffff);
    c.mesh.visible = !(selected === i);
  });
  if (selected !== null && selected < sheetCount(numFilters)) {
    cellsGroup.visible = true;
    cellsGroup.position.copy(cubes[selected].group.position);
    callout.pos.set(cubes[selected].group.position.x, CUBE_Y + 0.46, 0);
    setVis(callout, true);
  } else {
    cellsGroup.visible = false;
    setVis(callout, false);
  }
  gridIn.visible = spatial;
  gridOut.visible = spatial;
  patch.visible = spatial;
  patchEdge.visible = spatial;
}

/* ── state setters ─────────────────────────────────────────────────── */
const slider = document.getElementById('numFilters');
const nfVal = document.getElementById('nfVal');
const btnEmph = document.getElementById('btnEmph');

function setFilters(C, fromSlider) {
  C = Math.max(1, Math.min(96, Math.round(C)));
  if (C !== numFilters) {
    numFilters = C;
    T_OUT = rebuildOutput(C);
    layoutCubes(C);
    if (selected !== null && selected >= sheetCount(C)) selected = sheetCount(C) - 1;
  }
  nfVal.textContent = C;
  if (!fromSlider) slider.value = C;
  updateLabels(C);
  applyStyles();
}

function selectFilter(i) {
  selected = (selected === i) ? null : i;
  applyStyles();
}

function setEmphasis(e) {
  emphasis = e;
  btnEmph.textContent = 'Emphasis: ' + emphasis;
  applyStyles();
}

setFilters(96);
setEmphasis('Channel view');

/* ── UI wiring ─────────────────────────────────────────────────────── */
slider.addEventListener('input', () => { tween = null; setFilters(+slider.value, true); });
btnEmph.addEventListener('click', () =>
  setEmphasis(emphasis === 'Channel view' ? 'Spatial view' : 'Channel view'));
document.getElementById('btnClear').addEventListener('click', () => { selected = null; applyStyles(); hidePopup(); });

/* ── guided demo ───────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1 · The layer at full size',
    narr: 'A 3-channel 128×128 input enters a bank of 96 3×3 filters and leaves as a 96-channel 128×128 tensor. Only the slab thickness changes.',
    nf: 96, emph: 'Channel view', sel: null
  },
  {
    title: '2 · One filter at a time',
    narr: 'Shrink the bank to a single filter: the output collapses to one thin sheet. One filter produces exactly one output channel.',
    nf: 1, emph: 'Channel view', sel: null
  },
  {
    title: '3 · Count the weights',
    narr: 'The highlighted filter covers 3×3 spatially across all 3 input channels — 27 weights per filter, so 96 filters hold 96 × 27 = 2592 weights plus biases.',
    nf: 8, emph: 'Channel view', sel: 2
  },
  {
    title: '4 · Spatial size is untouched',
    narr: 'Spatial view: both faces are the same 128×128 square regardless of filter count. Depth grows, the image grid does not.',
    nf: 96, emph: 'Spatial view', sel: null
  }
];
let stepIdx = 0;
let tween = null;
const stepTitle = document.getElementById('stepTitle');
const stepNarr = document.getElementById('stepNarr');

function tweenFilters(target) {
  const from = numFilters, t0 = performance.now(), dur = 750;
  if (from === target) { tween = null; return; }
  tween = () => {
    const p = Math.min(1, (performance.now() - t0) / dur);
    const e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
    setFilters(from + (target - from) * e);
    if (p >= 1) tween = null;
  };
}

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  stepTitle.textContent = s.title;
  stepNarr.textContent = s.narr;
  setEmphasis(s.emph);
  tweenFilters(s.nf);
  selected = s.sel;
  if (numFilters === s.nf) setFilters(s.nf);
  applyStyles();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

(function demoLoop() {
  requestAnimationFrame(demoLoop);
  if (tween) tween();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

