// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC — built exactly as listed
// input slab sheets (3)     → BoxGeometry(0.25, 3.0, 3.0) white MeshBasic + EdgesGeometry black
// output slab sheets (<=7)  → BoxGeometry(T/N, 3.0, 3.0) white MeshBasic + EdgesGeometry black, T = f(C)
// filter box                → ShapeGeometry rounded-rect RING (black, thick) + white inner fill
// block arrows (2)          → ShapeGeometry 7-point hollow arrow RING (black outline)
// headers / dims / ellipses → addLabel() HTML, serif
// [hidden until asked] filter cubes (min(C,8)) → BoxGeometry(0.46) white + black edges + 3×3 face grids
// [hidden until asked] selected filter cells   → 27 × BoxGeometry(0.095) red
// [hidden until asked] face grids (2) 8×8 on the 128×128 faces + 3×3 receptive-field patch
*/

const BLACK = 0x000000, RED = 0xd64545, TINT = 0xf6d0d0, GREY = 0x9a9a9a;

const SLAB_H = 3.0, SLAB_D = 3.0;      // 128 (up) and 128 (receding)
const T_IN = 0.75;                     // 3 input channels (screen-horizontal)
const X_IN_R = -4.90, X_IN_L = X_IN_R - T_IN;
const X_OUT_L = 4.90;
const MAX_SHEETS = 7;
const T_OUT_MAX = 0.28 + 2.70;

/* ── helpers ───────────────────────────────────────────────────────── */
function mkLabel(html, pos, o = {}) {
  const e = addLabel(html, pos, o);
  e.div.style.fontFamily = 'Georgia,"Times New Roman",serif';
  return e;
}
function setVis(e, v) { e.div.style.visibility = v ? 'visible' : 'hidden'; }

function makeSheet(w, h, dd) {
  const geo = new THREE.BoxGeometry(w, h, dd);
  const mat = new THREE.MeshBasicMaterial({
    color: 0xffffff, transparent: true, opacity: 1,
    polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
  });
  const mesh = new THREE.Mesh(geo, mat);
  const eg = new THREE.EdgesGeometry(geo);
  const emat = new THREE.LineBasicMaterial({ color: BLACK });
  const edges = new THREE.LineSegments(eg, emat);
  const group = new THREE.Group();
  group.add(mesh, edges);
  return { group, mat, emat, geo, eg };
}
function disposeSheet(s) { s.geo.dispose(); s.eg.dispose(); s.mat.dispose(); s.emat.dispose(); }

function roundedRectShape(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2, y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y); s.absarc(x + w - r, y + r, r, -Math.PI / 2, 0, false);
  s.lineTo(x + w, y + h - r); s.absarc(x + w - r, y + h - r, r, 0, Math.PI / 2, false);
  s.lineTo(x + r, y + h); s.absarc(x + r, y + h - r, r, Math.PI / 2, Math.PI, false);
  s.lineTo(x, y + r); s.absarc(x + r, y + r, r, Math.PI, 1.5 * Math.PI, false);
  return s;
}
function ringMesh(outerShape, innerShape, color) {
  const hole = new THREE.Path(innerShape.getPoints(80).reverse());
  outerShape.holes.push(hole);
  const geo = new THREE.ShapeGeometry(outerShape, 24);
  return new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
}
function polyShape(pts) { return new THREE.Shape(pts.map(p => new THREE.Vector2(p[0], p[1]))); }

/* hollow block arrow (outline only) */
function blockArrow(L, sh, hh, hl, t) {
  const h = L / 2, b = L / 2 - hl, L2 = Math.hypot(hl, hh);
  const outer = [[-h, sh], [b, sh], [b, hh], [h, 0], [b, -hh], [b, -sh], [-h, -sh]];
  const y1 = sh - t, x1 = b + t;
  const P0x = b - t * hh / L2, P0y = hh - t * hl / L2;
  const y3 = P0y - (x1 - P0x) * hh / hl;
  const tipx = h - t * L2 / hh;
  const inner = [[-h + t, y1], [x1, y1], [x1, y3], [tipx, 0], [x1, -y3], [x1, -y1], [-h + t, -y1]];
  return ringMesh(polyShape(outer), polyShape(inner), BLACK);
}

/* ── input slab (3 sheets) ─────────────────────────────────────────── */
const inGroup = new THREE.Group(); scene.add(inGroup);
const inSheets = [];
for (let i = 0; i < 3; i++) {
  const t = T_IN / 3;
  const s = makeSheet(t, SLAB_H, SLAB_D);
  s.group.position.set(X_IN_L + (i + 0.5) * t, 0, 0);
  inGroup.add(s.group);
  inSheets.push(s);
}

/* input hover proxy (static, registered once) */
const proxyMat = () => new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
const inProxy = new THREE.Mesh(new THREE.BoxGeometry(T_IN, SLAB_H, SLAB_D), proxyMat());
inProxy.position.set(X_IN_L + T_IN / 2, 0, 0);
scene.add(inProxy);
registerInteractive(inProxy, {
  title: 'Input tensor x_in ∈ ℝ³ˣ¹²⁸ˣ¹²⁸',
  tooltip: 'Input: 3 channels of 128×128',
  body: 'Three 128×128 feature maps (e.g. R, G, B). The two big square faces are the 128×128 spatial grid; the slab is only 3 sheets thick because it has 3 channels.'
});

/* ── filter box ────────────────────────────────────────────────────── */
const BOX_W = 4.60, BOX_H = 2.30, BOX_R = 0.35, BOX_T = 0.075;
const boxGroup = new THREE.Group(); scene.add(boxGroup);
const boxFill = new THREE.Mesh(
  new THREE.ShapeGeometry(roundedRectShape(BOX_W - 2 * BOX_T, BOX_H - 2 * BOX_T, BOX_R - BOX_T), 24),
  new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide })
);
boxFill.position.z = -0.004;
boxGroup.add(boxFill);
boxGroup.add(ringMesh(
  roundedRectShape(BOX_W, BOX_H, BOX_R),
  roundedRectShape(BOX_W - 2 * BOX_T, BOX_H - 2 * BOX_T, BOX_R - BOX_T),
  BLACK));
registerInteractive(boxFill, {
  title: 'Filter bank with 3×3 filters',
  tooltip: 'The bank of 3×3 filters',
  body: 'The bank holds C filters. Each one is 3×3 spatially and spans all 3 input channels, i.e. 3×3×3 = 27 weights (+1 bias). Each filter is convolved over the whole 128×128 image and yields ONE output channel.'
});

/* ── two hollow arrows ─────────────────────────────────────────────── */
const arrowL = blockArrow(1.35, 0.26, 0.525, 0.62, 0.06); arrowL.position.set(-3.45, 0, 0);
const arrowR = blockArrow(1.35, 0.26, 0.525, 0.62, 0.06); arrowR.position.set(3.45, 0, 0);
scene.add(arrowL, arrowR);

/* ── output slab (rebuilt by the slider) ───────────────────────────── */
const outGroup = new THREE.Group(); scene.add(outGroup);
let outSheets = [];
function outThickness(C) { return 0.28 + 2.70 * (C / 96); }
function sheetCount(C) { return Math.min(Math.round(C), MAX_SHEETS); }

const outProxy = new THREE.Mesh(new THREE.BoxGeometry(1, SLAB_H, SLAB_D), proxyMat());
scene.add(outProxy);
registerInteractive(outProxy, {
  title: 'Output tensor x_out ∈ ℝ^{C×128×128}',
  tooltip: 'Output: one channel per filter',
  body: 'Same 128×128 spatial size as the input — only the channel count changed, from 3 to the number of filters in the bank. Slab thickness = channel count.'
});

function rebuildOutput(C) {
  for (const s of outSheets) { outGroup.remove(s.group); disposeSheet(s); }
  outSheets = [];
  const T = outThickness(C), N = sheetCount(C), t = T / N;
  for (let i = 0; i < N; i++) {
    const s = makeSheet(t, SLAB_H, SLAB_D);
    s.group.position.set(X_OUT_L + (i + 0.5) * t, 0, 0);
    outGroup.add(s.group);
    outSheets.push(s);
  }
  outProxy.scale.set(T, 1, 1);
  outProxy.position.set(X_OUT_L + T / 2, 0, 0);
  return T;
}

/* bounds anchor so slider changes never re-frame the figure */
const boundsAnchor = new THREE.Mesh(new THREE.BoxGeometry(0.002, SLAB_H, SLAB_D),
  new THREE.MeshBasicMaterial());
boundsAnchor.position.set(X_OUT_L + T_OUT_MAX, 0, 0);
boundsAnchor.visible = false;
scene.add(boundsAnchor);

/* ── spatial-view overlays (hidden by default) ─────────────────────── */
function makeGrid(n, size, color) {
  const pts = [], h = size / 2;
  for (let i = 0; i <= n; i++) {
    const u = -h + size * i / n;
    pts.push(new THREE.Vector3(0, u, -h), new THREE.Vector3(0, u, h));
    pts.push(new THREE.Vector3(0, -h, u), new THREE.Vector3(0, h, u));
  }
  return new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color }));
}
const gridIn = makeGrid(8, SLAB_D, 0x8a8a8a);
gridIn.position.set(X_IN_R + 0.01, 0, 0);
const gridOut = makeGrid(8, SLAB_D, 0x8a8a8a);
gridIn.visible = gridOut.visible = false;
scene.add(gridIn, gridOut);

const patchGeo = new THREE.PlaneGeometry(SLAB_D * 3 / 8, SLAB_D * 3 / 8).rotateY(Math.PI / 2);
const patch = new THREE.Mesh(patchGeo,
  new THREE.MeshBasicMaterial({ color: RED, transparent: true, opacity: 0.35, side: THREE.DoubleSide }));
patch.position.set(X_IN_R + 0.015, -0.19, 0.38);
const patchEdge = new THREE.LineSegments(new THREE.EdgesGeometry(patchGeo),
  new THREE.LineBasicMaterial({ color: RED }));
patchEdge.position.copy(patch.position);
patch.visible = patchEdge.visible = false;
scene.add(patch, patchEdge);

/* ── filter cubes inside the bank (hidden by default) ──────────────── */
const CUBE = 0.46, PITCH = 0.56, CUBE_Y = -2.00, MAX_CUBES = 8;
const cubesGroup = new THREE.Group(); cubesGroup.visible = false; scene.add(cubesGroup);
const cubes = [];

function cubeGrid(size) {
  const h = size / 2, s = size / 3, pts = [];
  for (let i = 1; i <= 2; i++) {
    const u = -h + i * s;
    // front face z = +h
    pts.push(new THREE.Vector3(u, -h, h), new THREE.Vector3(u, h, h));
    pts.push(new THREE.Vector3(-h, u, h), new THREE.Vector3(h, u, h));
    // top face y = +h
    pts.push(new THREE.Vector3(u, h, -h), new THREE.Vector3(u, h, h));
    pts.push(new THREE.Vector3(-h, h, u), new THREE.Vector3(h, h, u));
    // right face x = +h
    pts.push(new THREE.Vector3(h, u, -h), new THREE.Vector3(h, u, h));
    pts.push(new THREE.Vector3(h, -h, u), new THREE.Vector3(h, h, u));
  }
  return new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: GREY }));
}

for (let i = 0; i < MAX_CUBES; i++) {
  const geo = new THREE.BoxGeometry(CUBE, CUBE, CUBE);
  const mat = new THREE.MeshBasicMaterial({
    color: 0xffffff, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
  });
  const mesh = new THREE.Mesh(geo, mat);
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({ color: BLACK }));
  const grid = cubeGrid(CUBE);
  const g = new THREE.Group(); g.add(mesh, edges, grid);
  cubesGroup.add(g);
  cubes.push({ group: g, mesh, mat, edges, grid });
  registerInteractive(mesh, {
    title: 'One 3×3×3 filter',
    body: 'A single filter spans all 3 input channels: 3×3 spatial × 3 channels = 27 weights (+1 bias). Sliding it over the 128×128 image produces exactly ONE output channel — so C filters give C output channels.',
    tooltip: 'Filter: 3×3×3 = 27 weights',
    onClick: () => selectFilter(i)
  });
}

/* the 27 weight cells of the selected filter */
const cellsGroup = new THREE.Group(); cellsGroup.visible = false; scene.add(cellsGroup);
{
  const cs = 0.095, gap = CUBE / 3;
  for (let a = 0; a < 3; a++) for (let b = 0; b < 3; b++) for (let c = 0; c < 3; c++) {
    const geo = new THREE.BoxGeometry(cs, cs, cs);
    const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({
      color: RED, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
    }));
    const e = new THREE.LineSegments(new THREE.EdgesGeometry(geo),
      new THREE.LineBasicMaterial({ color: 0x7a1e1e }));
    const g = new THREE.Group(); g.add(m, e);
    g.position.set((a - 1) * gap, (b - 1) * gap, (c - 1) * gap);
    cellsGroup.add(g);
  }
}

/* ── state + initial build, then camera ────────────────────────────── */
let numFilters = 96;
let emphasis = 'Channel view';
let cubesShown = false;
let selected = null;
let T_OUT = rebuildOutput(numFilters);
layoutCubes(numFilters);

setCameraView({
  projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5,
  rollDeg: 0, heightFraction: 0.88
});

/* ── labels ────────────────────────────────────────────────────────── */
const DIM = { fontSize: '20px' }, HEAD = { fontSize: '22px' }, BOXF = { fontSize: '25px' };
const xIn = (X_IN_L + X_IN_R) / 2;

const hdrIn = mkLabel('<b>x</b><sub>in</sub> &isin; &#8477;<sup>3&times;128&times;128</sup>',
  new THREE.Vector3(xIn, 2.75, 0), HEAD);
const hdrOut = mkLabel('', new THREE.Vector3(0, 2.75, 0), HEAD);

const lblIn3 = mkLabel('3', new THREE.Vector3(xIn, -1.5, 1.5),
  Object.assign({ offset: [0, 24] }, DIM));
const lblOutC = mkLabel('96', new THREE.Vector3(0, -1.5, 1.5),
  Object.assign({ offset: [0, 24] }, DIM));

mkLabel('128', new THREE.Vector3(X_IN_L, 0, 1.5), Object.assign({ offset: [-30, 0] }, DIM));
mkLabel('128', new THREE.Vector3(X_IN_L, 1.5, 0), Object.assign({ offset: [-28, -20] }, DIM));

const lblOutH = mkLabel('128', new THREE.Vector3(0, 0.2, -1.5), Object.assign({ offset: [30, 0] }, DIM));
const lblOutD = mkLabel('128', new THREE.Vector3(0, -1.5, 0), Object.assign({ offset: [30, 22] }, DIM));

mkLabel('Filter Bank with', new THREE.Vector3(0, 0.40, 0.03), BOXF);
mkLabel('3x3 filters', new THREE.Vector3(0, -0.40, 0.03), BOXF);

const ellTop = mkLabel('&middot;&middot;&middot;', new THREE.Vector3(0, 1.51, -0.4),
  { fontSize: '24px', bold: true });
const ellFront = mkLabel('&middot;&middot;&middot;', new THREE.Vector3(0, -0.55, 1.52),
  { fontSize: '24px', bold: true });

const callout = mkLabel('3&times;3&times;3 = 27 weights', new THREE.Vector3(0, CUBE_Y + 0.45, 0),
  { fontSize: '13px', color: '#a01f1f', bold: true, background: '#ffffff' });
setVis(callout, false);

const cubesCaption = mkLabel('', new THREE.Vector3(0, CUBE_Y - 0.45, 0),
  { fontSize: '13px', color: '#555' });
setVis(cubesCaption, false);

/* ── layout / style updates ────────────────────────────────────────── */
function layoutCubes(C) {
  const n = Math.min(Math.round(C), MAX_CUBES);
  for (let i = 0; i < MAX_CUBES; i++) {
    cubes[i].group.visible = i < n;
    cubes[i].group.position.set((i - (n - 1) / 2) * PITCH, CUBE_Y, 0);
  }
}

function updateLabels(C) {
  const T = outThickness(C), xc = X_OUT_L + T / 2, xR = X_OUT_L + T;
  hdrOut.div.innerHTML = '<b>x</b><sub>out</sub> &isin; &#8477;<sup>' + C + '&times;128&times;128</sup>';
  hdrOut.pos.set(xc, 2.75, 0);
  lblOutC.div.innerHTML = String(C);
  lblOutC.pos.set(xc, -1.5, 1.5);
  lblOutH.pos.set(xR, 0.2, -1.5);
  lblOutD.pos.set(xR, -1.5, 0);
  ellTop.pos.set(X_OUT_L + T * 0.60, 1.51, -0.40);
  ellFront.pos.set(X_OUT_L + T * 0.45, -0.55, 1.52);
  const many = C > MAX_SHEETS;
  setVis(ellTop, many); setVis(ellFront, many);
  gridOut.position.set(xR + 0.01, 0, 0);

  const shown = Math.min(C, MAX_CUBES);
  cubesCaption.div.innerHTML = shown < C
    ? shown + ' of ' + C + ' filters in the bank'
    : (C === 1 ? 'the 1 filter in the bank' : 'the ' + C + ' filters in the bank');

  document.getElementById('paramInfo').innerHTML =
    C + ' filters &times; 27 weights = <b>' + (C * 27) + '</b> weights (+ ' + C + ' biases)';
}

function applyStyles() {
  const spatial = emphasis === 'Spatial view';
  const faceOp = spatial ? 0.30 : 1.0;
  const edgeCol = spatial ? GREY : BLACK;

  inSheets.forEach(s => {
    const hl = selected !== null;
    s.mat.color.set(hl ? TINT : 0xffffff);
    s.mat.opacity = faceOp;
    s.emat.color.set(hl ? RED : edgeCol);
  });
  outSheets.forEach((s, i) => {
    const hl = selected !== null && i === selected;
    s.mat.color.set(hl ? TINT : 0xffffff);
    s.mat.opacity = faceOp;
    s.emat.color.set(hl ? RED : edgeCol);
  });
  cubes.forEach((c, i) => {
    c.mat.color.set(selected === i ? TINT : 0xffffff);
    c.mesh.visible = !(selected === i);
    c.grid.visible = !(selected === i);
  });

  const cubesOn = cubesShown;
  cubesGroup.visible = cubesOn;
  setVis(cubesCaption, cubesOn);

  if (cubesOn && selected !== null && selected < Math.min(numFilters, MAX_CUBES)) {
    cellsGroup.visible = true;
    cellsGroup.position.copy(cubes[selected].group.position);
    callout.pos.set(cubes[selected].group.position.x, CUBE_Y + 0.48, 0);
    setVis(callout, true);
  } else {
    cellsGroup.visible = false;
    setVis(callout, false);
  }

  gridIn.visible = spatial;
  gridOut.visible = spatial;
  patch.visible = spatial;
  patchEdge.visible = spatial;
}

/* ── state setters ─────────────────────────────────────────────────── */
const slider = document.getElementById('numFilters');
const nfVal = document.getElementById('nfVal');
const btnEmph = document.getElementById('btnEmph');
const btnCubes = document.getElementById('btnCubes');

function setFilters(C, fromSlider) {
  C = Math.max(1, Math.min(96, Math.round(C)));
  if (C !== numFilters) {
    numFilters = C;
    T_OUT = rebuildOutput(C);
    layoutCubes(C);
    if (selected !== null && selected >= Math.min(C, MAX_CUBES)) selected = Math.min(C, MAX_CUBES) - 1;
  }
  nfVal.textContent = C;
  if (!fromSlider) slider.value = C;
  updateLabels(C);
  applyStyles();
}

function selectFilter(i) {
  if (!cubesShown) return;
  selected = (selected === i) ? null : i;
  applyStyles();
}

function setEmphasis(e) {
  emphasis = e;
  btnEmph.textContent = 'Emphasis: ' + emphasis;
  btnEmph.classList.toggle('active', emphasis === 'Spatial view');
  applyStyles();
}

function setCubesShown(on) {
  cubesShown = on;
  if (!on) selected = null;
  btnCubes.textContent = on ? 'Hide filters (printed figure)' : 'Show filters inside the bank';
  btnCubes.classList.toggle('active', on);
  applyStyles();
}

setFilters(96);
setEmphasis('Channel view');
setCubesShown(false);

/* ── UI wiring ─────────────────────────────────────────────────────── */
slider.addEventListener('input', () => { tween = null; setFilters(+slider.value, true); });
btnEmph.addEventListener('click', () =>
  setEmphasis(emphasis === 'Channel view' ? 'Spatial view' : 'Channel view'));
btnCubes.addEventListener('click', () => { setCubesShown(!cubesShown); hidePopup(); });
document.getElementById('btnClear').addEventListener('click', () => {
  selected = null; applyStyles(); hidePopup();
});

/* ── guided demo ───────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1 · The layer at full size',
    narr: 'A 3-channel 128×128 input enters a bank of 96 3×3 filters and leaves as a 96-channel 128×128 tensor. Only the slab thickness changes.',
    nf: 96, emph: 'Channel view', cubes: false, sel: null
  },
  {
    title: '2 · One filter at a time',
    narr: 'Shrink the bank to a single filter: the output collapses to one thin sheet. One filter produces exactly one output channel.',
    nf: 1, emph: 'Channel view', cubes: false, sel: null
  },
  {
    title: '3 · Count the weights',
    narr: 'The bank is opened. The highlighted filter covers 3×3 spatially across all 3 input channels — 27 weights per filter, so 96 filters hold 96 × 27 = 2592 weights plus biases.',
    nf: 8, emph: 'Channel view', cubes: true, sel: 2
  },
  {
    title: '4 · Spatial size is untouched',
    narr: 'Spatial view: both big faces stay the same 128×128 square regardless of filter count. Depth grows, the image grid does not.',
    nf: 96, emph: 'Spatial view', cubes: false, sel: null
  }
];
let stepIdx = 0;
let tween = null;
const stepTitle = document.getElementById('stepTitle');
const stepNarr = document.getElementById('stepNarr');

function tweenFilters(target) {
  const from = numFilters, t0 = performance.now(), dur = 750;
  if (from === target) { tween = null; return; }
  tween = () => {
    const p = Math.min(1, (performance.now() - t0) / dur);
    const e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
    setFilters(from + (target - from) * e);
    if (p >= 1) { tween = null; setFilters(target); applyStyles(); }
  };
}

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  stepTitle.textContent = s.title;
  stepNarr.textContent = s.narr;
  setEmphasis(s.emph);
  setCubesShown(s.cubes);
  tweenFilters(s.nf);
  if (numFilters === s.nf) setFilters(s.nf);
  selected = s.cubes ? s.sel : null;
  applyStyles();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

(function demoLoop() {
  requestAnimationFrame(demoLoop);
  if (tween) tween();
})();
